using System;
class SpellStatusChecks {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Main(){var c=new CombatState();c.ApplyPlayerDamage(2);c.ApplyDamage(2);c.BlockHealing(true);c.BlockHealing(false);Check(c.HealPlayer(2)==0&&c.HealMonster(2)==0,"healing prevention");c.ExpirePlayerTurnEffects();Check(c.PlayerHealingBlocked&&c.MonsterHealingBlocked,"effect survives casting turn end");c.EndRound();Check(c.PlayerHealingBlocked,"effect survives next turn start");c.ExpirePlayerTurnEffects();Check(c.HealPlayer(2)==2&&c.HealMonster(2)==2,"effect expires next turn end");c.ApplyMockery(false);Check(c.ConsumeMockery(false)&&!c.ConsumeMockery(false),"mockery consumed once");c.ApplyMockery(false);c.FinishMonsterTurnEffects();Check(!c.ConsumeMockery(false),"unused mockery expires monster turn end");c.ApplyMockery(true);c.ExpirePlayerTurnEffects();c.EndRound();Check(c.ConsumeMockery(true),"player mockery survives until next turn");c.ApplyMockery(true);c.ClearShortDurationEffects();Check(!c.ConsumeMockery(true)&&!c.PlayerHealingBlocked,"rest clears short effects");c.BlockHealing(true);c.GrantPlayerTemporaryHp(8);Check(c.PlayerTemporaryHp==8,"temporary hp not healing");c.GrantPlayerTemporaryHp(4);Check(c.PlayerTemporaryHp==8,"temporary hp do not stack");c.ResetBattle();Check(!c.PlayerHealingBlocked&&!c.MonsterHealingBlocked&&c.PlayerTemporaryHp==0,"reset clears effects");Console.WriteLine("PASS: healing prevention duration, single-use disadvantage, turn expiry, rest, temporary HP and reset");}
}
